import{_ as t,c as o,a2 as u,o as q}from"./chunks/framework.CqbvlPrP.js";const c=JSON.parse('{"title":"第六章：重要教法：斧头柄经，乞食经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/佛陀传奇/第六章：重要教法：斧头柄经，乞食经.md","filePath":"meditation/佛陀传奇/第六章：重要教法：斧头柄经，乞食经.md"}'),e={name:"meditation/佛陀传奇/第六章：重要教法：斧头柄经，乞食经.md"};function a(_,p,r,n,i,s){return q(),o("div",null,p[0]||(p[0]=[u('<h1 id="第六章-重要教法-斧头柄经-乞食经" tabindex="-1">第六章：重要教法：斧头柄经，乞食经 <a class="header-anchor" href="#第六章-重要教法-斧头柄经-乞食经" aria-label="Permalink to &quot;第六章：重要教法：斧头柄经，乞食经&quot;">​</a></h1><p>《佛陀传奇：从皇宫到涅槃的光明之路》</p><p>6.12斧头柄经（相应部22相应101经/斧头柄经(蕴相应/蕴篇/修多罗)</p><p>【开篇】</p><p>在舍卫城（背景）。&quot;比丘们，我说漏尽是对于知者、见者而言，而非不知者、不见者。比丘们，知什么、见什么而有漏尽呢？&#39;这是色，这是色的生起，这是色的灭没；这是受...这是想...这是行...这是识，这是识的生起，这是识的灭没&#39;——比丘们，如此知、如此见者，便有漏尽。&quot;</p><p>【第一部分：未修习者的比喻】</p><p>&quot;比丘们，对于不勤修习的比丘，即便生起这样的愿望：&#39;啊！愿我的心无取著而从诸漏解脱！&#39;然而他的心却不能无取著而从诸漏解脱。这是什么原因呢？应当说是&#39;因为未修习&#39;。未修习什么？未修习四念处、未修习四正勤、未修习四神足、未修习五根、未修习五力、未修习七觉支、未修习八正道。&quot;</p><p>【母鸡孵蛋的比喻】</p><p>&quot;比丘们，就像母鸡有八个、十个或十二个蛋。如果这些蛋没有被母鸡好好地孵化，没有好好地温暖，没有好好地培育。即便这只母鸡生起这样的愿望：&#39;啊！愿我的小鸡们用脚爪尖或鸟喙啄破蛋壳，平安地出生！&#39;然而这些小鸡是不可能用脚爪尖或鸟喙啄破蛋壳，平安地出生的。这是什么原因呢？因为比丘们，那母鸡的八个、十个或十二个蛋，没有被好好地孵化，没有好好地温暖，没有好好地培育。&quot;</p><p>【第二部分：精进修习者】</p><p>&quot;比丘们，对于精进修习的比丘，即便没有生起这样的愿望：&#39;啊！愿我的心无取著而从诸漏解脱！&#39;然而他的心却能无取著而从诸漏解脱。这是什么原因呢？应当说是&#39;因为已修习&#39;。已修习什么？已修习四念处、已修习四正勤、已修习四神足、已修习五根、已修习五力、已修习七觉支、已修习八正道。&quot;</p><p>【善于孵蛋的比喻】</p><p>&quot;比丘们，就像母鸡有八个、十个或十二个蛋。这些蛋被母鸡好好地孵化，好好地温暖，好好地培育。即便这只母鸡没有生起这样的愿望：&#39;啊！愿我的小鸡们用脚爪尖或鸟喙啄破蛋壳，平安地出生！&#39;然而这些小鸡却能够用脚爪尖或鸟喙啄破蛋壳，平安地出生。这是什么原因呢？因为比丘们，那母鸡的八个、十个或十二个蛋，已被好好地孵化，好好地温暖，好好地培育。&quot;</p><p>【斧柄的比喻】</p><p>&quot;比丘们，就像木匠或木匠的徒弟在斧柄上能看到手指印和拇指印。虽然他并不知道：&#39;今天我的斧柄磨损了这么多，昨天磨损了这么多，前天磨损了这么多。&#39;但当磨损时，他知道它已经磨损了。同样地，比丘们，精进修习的比丘虽然并不知道：&#39;今天我的漏尽了这么多，昨天尽了这么多，前天尽了这么多。&#39;但当漏尽时，他知道它们已经尽了。&quot;</p><p>【船绳的比喻】</p><p>&quot;比丘们，就像一艘海船，用藤绳捆绑，在水中度过雨季后，被拖上岸，经受风吹日晒，其藤绳在雨季的阵雨中很容易就松弛腐朽。同样地，比丘们，精进修习的比丘，他的结缚很容易就松弛腐朽。&quot;</p><p>第九经终。</p><p>经文通过多个生动的比喻说明了修行的重要性，以及如何通过精进修习来达到解脱的境界。</p><p>6.13乞食经（相应部22相应80经/乞食经(蕴相应/蕴篇/修多罗)</p><p>【背景】</p><p>一时，世尊住在释迦族的迦毗罗卫城尼拘律园。那时，世尊因某种原因遣散比丘僧团后，在上午时分，着衣持钵，进入迦毗罗卫城乞食。在迦毗罗卫城乞食完毕，饭后返回，为了午休而前往大林。进入大林后，在一棵木苹婆树下坐下午休。</p><p>【世尊的思维】</p><p>那时，世尊独处静坐时，心中生起这样的思维：&quot;我已遣散了比丘僧团。其中有些是新出家不久、最近才来到这里的比丘。如果他们看不见我，可能会有所改变，会有转变。就像小牛犊看不见母牛，可能会有所改变，会有转变。同样地，这些新出家不久、最近才来到这里的比丘，如果看不见我，可能会有所改变，会有转变。就像幼苗得不到水分，可能会有所改变，会有转变。我是否应该像以前那样，现在也继续摄受比丘僧团呢？&quot;</p><p>【梵天的请求】</p><p>这时，娑婆世界主梵天知道了世尊的心念，就像壮士伸直弯曲的手臂或弯曲伸直的手臂那样快速地从梵界消失，出现在世尊面前。然后，娑婆世界主梵天偏袒右肩，向世尊合掌，对世尊说：&quot;确实如此，世尊！确实如此，善逝！尊者世尊，比丘僧团已被遣散。其中有些是新出家不久、最近才来到这里的比丘。如果他们看不见世尊，可能会有所改变，会有转变...（重复世尊的思维内容）...请世尊欢喜摄受比丘僧团！请世尊鼓励比丘僧团！请世尊像以前那样，现在也继续摄受比丘僧团！&quot;</p><p>【世尊的接受】</p><p>世尊以沉默表示同意。娑婆世界主梵天知道世尊已经同意，向世尊礼敬，右绕后就在那里消失了。</p><p>【召集比丘】</p><p>傍晚时分，世尊从禅思中起来，前往尼拘律园。到达后，坐在准备好的座位上。坐下后，世尊施展神通力，使那些比丘们一个接一个地怀着恭敬心来到他这里。那些比丘也确实一个接一个地怀着恭敬心来到世尊这里，礼敬世尊后，坐在一旁。</p><p>【世尊的教导】</p><p>世尊对坐在一旁的比丘们说：</p><p>&quot;比丘们，在各种生活方式中，乞食是最低下的。在世间中，&#39;持钵乞食者&#39;是一种诅咒语。然而，善男子们为了目的而接受这种生活，是出于有益的原因；不是被国王强迫，不是被盗贼胁迫，不是因负债，不是因恐惧，不是因失去生计；而是因为我们陷入了生、老、死、忧、悲、苦、忧恼之中，被苦所困，被苦所迫。也许我们能找到这整个苦蕴的终结。&quot;</p><p>【恶行比喻】</p><p>&quot;比丘们，如果这样出家的善男子充满贪欲、对欲望有强烈的渴求、心怀恶意、思想污浊、失念、不正知、心不专注、心神散乱、诸根放逸，就像一根两头燃烧、中间沾粪的火把，既不能在村里用作柴薪，也不能在林中用作柴薪。比丘们，我说这种人既失去了在家的享受，又没有完成沙门的目标。&quot;</p><p>【不善寻的止息】</p><p>&quot;比丘们，有三种不善寻：欲寻、恚寻、害寻。这三种不善寻在哪里完全止息？在四念处中安住心念，或者修习无相定。比丘们，修习无相定是足够的。修习、多修习无相定能带来大果报、大利益。&quot;</p><p>【二种见的超越】</p><p>&quot;比丘们，有两种见：有见和无见。在这里，多闻圣弟子这样思维：&#39;在这世间上，有没有什么是我执取了而不会受到指责的？&#39;他了知：&#39;在这世间上，没有什么是我执取了而不会受到指责的。因为我如果执取，就只会执取色、受、想、行、识。由于执取为缘而有有，由有为缘而有生，由生为缘而有老死、忧悲苦恼忧恼。如此这整个苦蕴集起。&#39;&quot;</p><p>【五蕴的观察】</p><p>&quot;比丘们，你们认为如何，色是常还是无常？&quot; &quot;无常，世尊。&quot; &quot;无常的是苦还是乐？&quot; &quot;是苦，世尊。&quot; &quot;对于无常、苦、变易之法，是否适合认为：&#39;这是我的，这是我，这是我的自我&#39;？&quot; &quot;不适合，世尊。&quot;（对受、想、行、识也如是问答）...&quot;因此，比丘们，如是见者...了知：不再有后有。&quot;</p><p>第八经终。</p><p>经文阐述了出家修行的真正意义，以及如何通过正确的修行方法来超越执著，达到解脱。</p>',43)]))}const l=t(e,[["render",a]]);export{c as __pageData,l as default};
